package bench

import (
	"fmt"
	"github.com/gosimd/pretok"
	"slices"
	"unicode/utf8"
)

// Reference is generated by the native HF oracle during this run, never loaded
// from a stored expected-output file. Its large arrays are discarded after Verify.
type Reference struct {
	Corpus     string             `json:"corpus"`
	Size       int                `json:"size"`
	PatternSHA string             `json:"pattern_sha256"`
	InputSHA   string             `json:"input_sha256"`
	Requests   []ReferenceRequest `json:"requests"`
}
type ReferenceRequest struct {
	Start   int      `json:"start"`
	End     int      `json:"end"`
	Matches [][2]int `json:"matches"`
	Split   [][2]int `json:"split"`
}

func checkedSpans(src string, raw [][2]int, partition bool) ([]pretok.Span, error) {
	out := make([]pretok.Span, len(raw))
	end := 0
	for i, s := range raw {
		if s[0] < end || partition && s[0] != end || s[1] <= s[0] || s[1] > len(src) || !utf8.ValidString(src[end:s[0]]) || !utf8.ValidString(src[s[0]:s[1]]) {
			return nil, fmt.Errorf("invalid reference span %d", i)
		}
		out[i] = pretok.Span{Start: s[0], End: s[1]}
		end = s[1]
	}
	if partition && end != len(src) {
		return nil, fmt.Errorf("incomplete reference partition")
	}
	return out, nil
}

func Verify(re *pretok.Regexp, patternSHA string, b *Batch, ref Reference) error {
	b.Verified = false
	if ref.Corpus != b.ID || ref.Size != b.Size || ref.PatternSHA != patternSHA || ref.InputSHA != b.InputSHA || len(ref.Requests) != len(b.Requests) {
		return fmt.Errorf("reference identity or request count mismatch for %s/%d", b.ID, b.Size)
	}
	matches, spans, capacity := 0, 0, 0
	for i, r := range b.Requests {
		want := ref.Requests[i]
		if want.Start != r.Start || want.End != r.End {
			return fmt.Errorf("reference input range mismatch in request %d", i)
		}
		split, err := checkedSpans(r.Text, want.Split, true)
		if err != nil {
			return err
		}
		match, err := checkedSpans(r.Text, want.Matches, false)
		if err != nil {
			return err
		}
		got, err := re.Split(r.Text, nil)
		if err != nil {
			return err
		}
		if !slices.Equal(got, split) {
			return mismatch("pretok-split", b.ID, b.Size, i, r.Text, got, split)
		}
		cursor, err := re.Cursor(r.Text)
		if err != nil {
			return err
		}
		got = got[:0]
		for s, ok := cursor.Next(); ok; s, ok = cursor.Next() {
			got = append(got, s)
		}
		if !slices.Equal(got, match) {
			return mismatch("pretok-cursor", b.ID, b.Size, i, r.Text, got, match)
		}
		matches += len(match)
		spans += len(split)
		capacity = max(capacity, len(split))
	}
	b.Matches, b.Spans, b.Capacity, b.Verified = matches, spans, capacity, true
	return nil
}
func (b *Batch) OutputCount(engine string) int {
	if engine == "pretok-cursor" || engine == "onig-iter" || engine == "onig-at" {
		return b.Matches
	}
	return b.Spans
}

func mismatch(engine, id string, size, index int, src string, got, want []pretok.Span) error {
	at := 0
	for at < len(got) && at < len(want) && got[at] == want[at] {
		at++
	}
	start := 0
	if at < len(want) {
		start = want[at].Start
	}
	lo := max(0, start-30)
	hi := min(len(src), start+90)
	return fmt.Errorf("%s %s/%d request %d: first mismatch span %d, got %v expected %v, nearby bytes %q", engine, id, size, index, at, got[max(0, at-1):min(len(got), at+2)], want[max(0, at-1):min(len(want), at+2)], src[lo:hi])
}
